def check_pqr(p, q, r):
    # Prerequisites: p, q, r are distinct primes, p < q < r, q+r=800
    if not is_prime(p) or not is_prime(q) or not is_prime(r):
        return False
    if p >= q or q >= r:
        return False
    if q + r != 800:
        return False

    # Constraints: A, B, C, D must be prime
    A = p + q - r  # p + (q-r)
    B = q + r - p  # 800 - p
    C = r + p - q  # p + (r-q)
    D = p + q + r  # p + 800

    if not is_prime(A):
        return False
    if not is_prime(B):
        return False
    if not is_prime(C):
        return False
    if not is_prime(D):
        return False

    return True

